/* ═══════════ UI: เลือกฟาร์ม → เลือกเล้า/รุ่นตู้ → 8 หัวข้อ + แก้ปัญหา ═══════════
   ⚠️ กติกาของไฟล์นี้: onclick ในสตริง HTML ส่งได้เฉพาะ "ตัวเลข index" กับ "คีย์รุ่น a-z0-9"
   ห้ามส่งชื่อฟาร์ม/ชื่อกลุ่มเป็นสตริง — ชื่อไทยมีช่องว่างและอัญประกาศ ทำให้แอตทริบิวต์แตก */
const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const nm=s=>String(s||'').replace(/ฟาร์ม|\s/g,'');
let FARMS=[],view={s:'home'};
const app=document.getElementById('app'),crumb=document.getElementById('crumb');

function loadFarms(){
  try{const s=localStorage.getItem('ppf_farms_v3');FARMS=s?(JSON.parse(s)||[]):[];}catch(e){FARMS=[];}
  if(!Array.isArray(FARMS))FARMS=[];
}
function curCf(){try{const u=JSON.parse(localStorage.getItem('ppf_ui')||'null');return u&&Number.isInteger(u.cf)?u.cf:0;}catch(_){return 0;}}
/* ใบตั้งค่าของฟาร์มนี้ (ถ้าหมอยืนยันแล้ว) */
function setOf(farmName){
  const n=nm(farmName);
  for(const k in FARMSET)if(n&&(n.indexOf(k)>=0||k.indexOf(n)>=0))return FARMSET[k];
  return null;
}
function farmOf(){return FARMS[view.f]||null;}
function groupOf(){const f=farmOf();if(!f||view.gi==null)return null;const fs=setOf(f.name);return (fs&&fs.groups[view.gi])||null;}
/* รุ่นตู้ที่พนักงานเลือกไว้เองต่อฟาร์ม (เครื่องนี้จำให้) */
function pickedModel(farmName){try{return (JSON.parse(localStorage.getItem('ppf_ctrl_model')||'{}'))[nm(farmName)]||'';}catch(_){return '';}}
function pickModel(i,mk){
  const f=FARMS[i];if(!f)return;
  try{const o=JSON.parse(localStorage.getItem('ppf_ctrl_model')||'{}');
    if(mk)o[nm(f.name)]=mk;else delete o[nm(f.name)];
    localStorage.setItem('ppf_ctrl_model',JSON.stringify(o));}catch(_){}
  if(mk)go({s:'topics',f:i,m:mk,gi:null});else render();
}
function go(v){view=v;render();try{window.scrollTo(0,0);}catch(_){}}
function tblHTML(t){
  if(!t)return '';
  return '<div class="tcap">'+esc(t.cap)+'</div><div class="twrap"><table><thead><tr>'
    +t.head.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'
    +t.rows.map(r=>'<tr>'+r.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
}
function warnHTML(list){return (list||[]).map(w=>'<div class="warn '+w[0]+'">'+w[1]+'</div>').join('');}
const gi$=()=>(view.gi==null?'null':view.gi);   // gi สำหรับฝังใน onclick

function render(){
  crumb.innerHTML='';
  if(view.s==='home')return renderHome();
  const M=MODELS[view.m];
  if(!M)return go({s:'home'});
  const g=groupOf();
  const label=(g?g.grp+' · ':'')+M.name;
  let bc='<button onclick="go({s:\'home\'})">⌂ เลือกฟาร์ม</button>';
  if(view.s!=='topics')bc+='<span>›</span><button onclick="go({s:\'topics\',f:'+view.f+',m:\''+view.m+'\',gi:'+gi$()+'})">'+esc(label)+'</button>';
  crumb.innerHTML=bc;
  if(view.s==='topics')return renderTopics(M,g);
  if(view.s==='page')return renderPage(M,g,view.t,false);
  if(view.s==='trouble')return renderPage(M,g,view.t,true);
  if(view.s==='check')return renderCheck(M,g);
}

function renderHome(){
  loadFarms();
  if(!FARMS.length){
    app.innerHTML='<div class="card"><div class="fname">📭 ยังไม่มีข้อมูลฟาร์มในเครื่องนี้</div><div class="fsub">เปิดแท็บอื่นในแอปให้ดึงข้อมูลจากคลาวด์ก่อน แล้วกลับมาหน้านี้อีกครั้ง — หน้านี้อ่านรายชื่อฟาร์มชุดเดียวกับแอปหลัก</div></div>';
    return;
  }
  let h='<div class="sech">เลือกฟาร์มของคุณ <small>— แล้วกดเล้า/รุ่นตู้ที่ฟาร์มคุณมี</small></div>';
  FARMS.forEach((f,i)=>{
    const fs=setOf(f.name), pk=pickedModel(f.name);
    h+='<div class="card"><div class="fname">🚜 '+esc(f.name)+'</div>';
    if(fs&&fs.partialManual){
      h+='<div class="fsub">✅ ยืนยันรุ่นตู้แล้ว ('+esc(fs.confirmed)+')</div>';
      fs.groups.forEach(function(g,gi){
        h+='<div class="grp" onclick="go({s:\'topics\',f:'+i+',m:\''+g.model+'\',gi:'+gi+'})">'
          +'<div><b>'+esc(g.grp)+'</b><div class="fsub">มีคู่มือครบ 8 หัวข้อแล้ว</div></div>'
          +'<span class="model">'+esc(MODELS[g.model].name)+'</span></div>';
      });
      h+='<div class="warn d" style="margin-top:9px">⛔ <b>เล้าที่ใช้ตู้ '+esc(fs.partialManual)+' ยังไม่มีคู่มือในระบบ</b> — '+esc(fs.partialManual)+' เป็นคนละยี่ห้อ เมนูคนละแบบ 🔴 <b>ห้ามเอาคู่มือ Big Herdsman หรือ Waterflame ไปกดตู้ '+esc(fs.partialManual)+'</b><br>ช่วยได้โดย: 📷 ถ่ายรูปหน้าตู้ + ป้ายชื่อรุ่น (SKOV มักเป็นตระกูล DOL) ส่งให้หมอ · 📄 ขอไฟล์คู่มือจากตัวแทนขาย</div>';
    }else if(fs&&fs.noManual){
      h+='<div class="fsub">✅ หมอระบุยี่ห้อตู้แล้ว ('+esc(fs.confirmed)+'): <b style="color:var(--ink)">'+esc(fs.brands)+'</b></div>'
       +'<div class="warn d" style="margin-top:9px">⛔ <b>ยังไม่มีคู่มือของยี่ห้อนี้ในระบบ</b> — คู่มือทั้ง 4 รุ่นที่มีเป็นของ Waterflame ซึ่งเมนูและลอจิกคนละแบบกับ '+esc(fs.brands)+' 🔴 <b>ห้ามหยิบคู่มือรุ่นอื่นไปเทียบกดตู้ของฟาร์มนี้</b></div>'
       +'<div class="fsub" style="margin-top:8px">สิ่งที่ช่วยให้มีคู่มือเร็วขึ้น: 📷 ถ่ายรูปหน้าตู้ + ป้ายชื่อรุ่น (มักติดข้างตู้หรือด้านในฝาตู้) ส่งให้หมอ/ผู้ดูแลระบบ · 📄 ขอไฟล์คู่มือจากตัวแทนขาย SKOV / Big Herdsman — ได้คู่มือเมื่อไหร่ ระบบจะมีครบ 8 หัวข้อ + หน้าแก้ปัญหาเหมือนรุ่นอื่น</div>';
    }else if(fs){
      h+='<div class="fsub">✅ ใบตั้งค่ายืนยันจากหมอแล้ว ('+esc(fs.confirmed)+') · '+fs.groups.length+' กลุ่มโรงเรือน</div>';
      fs.groups.forEach((g,gi)=>{
        h+='<div class="grp" onclick="go({s:\'topics\',f:'+i+',m:\''+g.model+'\',gi:'+gi+'})">'
          +'<div><b>'+esc(g.grp)+'</b><div class="fsub">'+esc(g.info.split('·').slice(0,2).join('·'))+'</div></div>'
          +'<span class="model">'+esc(MODELS[g.model].name)+'</span></div>';
      });
    }else{
      h+='<div class="fsub">⏳ หมอยังไม่ได้ระบุว่าเล้าไหนใช้ตู้รุ่นไหน — เลือกรุ่นที่ฟาร์มคุณมีได้เลย (เครื่องนี้จะจำไว้)</div>';
      if(pk&&MODELS[pk]){
        h+='<div class="grp" onclick="go({s:\'topics\',f:'+i+',m:\''+pk+'\',gi:null})">'
          +'<div><b>เปิดคู่มือ '+esc(MODELS[pk].name)+'</b><div class="fsub">รุ่นที่เลือกไว้ในเครื่องนี้</div></div>'
          +'<span class="model">'+esc(MODELS[pk].name)+'</span></div>'
          +'<button class="lnk" onclick="pickModel('+i+',\'\')">↺ เปลี่ยนรุ่นตู้</button>';
      }else{
        h+='<div class="mgrid">';
        for(const mk in MODELS)h+='<button class="mbtn" onclick="pickModel('+i+',\''+mk+'\')"><b>'+esc(MODELS[mk].name)+'</b><small>'+esc(MODELS[mk].era)+'</small></button>';
        h+='</div>';
      }
    }
    h+='</div>';
  });
  h+='<div class="card" style="border-color:rgba(251,191,36,.35)"><div class="fsub">📌 <b>ยังไม่รู้ว่าตู้ที่เล้าตัวเองเป็นรุ่นไหน?</b> ดูที่หน้าตู้ — จอสัมผัสสี = <b>Chickatron 20</b> · จอตัวเลขมีปุ่ม MENU / ENTER / HOME = <b>Temp 1200Plus</b> · จอตัวเลขมีปุ่ม Select / Program = <b>Temp 1200</b> · จอตัวเลขที่ต้องกดรหัสเลข 3 หลักทุกครั้ง = <b>TF716</b> · ถ้ายังไม่ชัวร์ ถ่ายรูปหน้าตู้ส่งให้หมอหรือผู้ดูแลระบบ</div></div>';
  app.innerHTML=h;
}

function renderTopics(M,g){
  const f=farmOf();
  let h='<div class="card"><div class="fname">'+(f?esc(f.name):'')+(g?' · '+esc(g.grp):'')+' <span class="model">'+esc(M.name)+'</span></div>';
  h+='<div class="fsub">'+(g?esc(g.info):esc(M.era))+'</div>';
  if(g&&g.specPending)h+='<div class="warn w" style="margin-top:10px">⚠️ <b>รุ่นตู้ยืนยันแล้ว แต่ยังไม่มีตัวเลขเฉพาะเล้ากลุ่มนี้</b> — ขั้นตอน "กดปุ่มไหน" ใช้ได้เต็มที่ (เป็นของรุ่นเครื่อง) แต่หัวข้อพัดลม (6–7) 🔴 ห้ามคีย์ตามตัวอย่าง เพราะขึ้นกับจำนวนพัดลมของหลังนั้น · ช่วยเดินนับพัดลมและผังช่องรีเลย์แจ้งผู้ดูแลระบบ จะได้ทำใบตั้งค่าให้</div>';
  if(!g)h+='<div class="warn w" style="margin-top:10px">⚠️ ฟาร์มนี้<b>ยังไม่มีใบตั้งค่าที่หมอยืนยัน</b> — ขั้นตอน "กดปุ่มไหน" ใช้ได้เต็มที่ (เป็นของรุ่นเครื่อง เหมือนกันทุกฟาร์ม) แต่<b>ตัวเลขในตารางเป็นค่าอ้างอิงของกลุ่ม PPF ไม่ใช่ของเล้าคุณ</b> — ห้ามคีย์ตามก่อนให้หมอยืนยัน โดยเฉพาะหัวข้อพัดลม (6–7) ที่ขึ้นกับจำนวนพัดลมของแต่ละเล้า</div>';
  h+='<div class="howto">🎛 <b>วิธีกดของ '+esc(M.name)+':</b> '+M.how+'</div></div>';
  if(g&&g.relay)h+='<div class="card">'+tblHTML(g.relay)+(g.relayNote?'<div class="ref" style="color:var(--muted)">'+g.relayNote+'</div>':'')+'</div>';
  h+='<div class="sech">⚙️ ตั้งค่าพื้นฐาน 8 หัวข้อ <small>— เรียงตามลำดับที่หมอกำหนด</small></div><div class="tgrid">';
  TOPIC_ORDER.forEach((k,i)=>{const t=M.topics[k];if(!t)return;
    const risky=!g&&PER_HOUSE.indexOf(k)>=0;
    h+='<div class="tcard'+(risky?' rq':'')+'" onclick="go({s:\'page\',f:'+view.f+',m:\''+view.m+'\',gi:'+gi$()+',t:\''+k+'\'})">'
      +'<span class="no">'+(i+1)+'</span><span class="ic">'+t.ic+'</span><div class="tt">'+esc(t.t)+'</div>'
      +'<div class="td">'+esc(String(t.why).split('—')[0].trim())+'</div>'
      +(risky?'<div class="td" style="color:var(--amber)">⚠️ ต้องมีใบตั้งค่ารายเล้า</div>':'')+'</div>';});
  h+='</div><div class="sech">🚨 เจอปัญหาเฉพาะหน้า <small>— เปิดหน้านี้ก่อนโทรตามใคร ไล่เช็กได้ทีละข้อ</small></div><div class="tgrid">';
  TROUBLE_ORDER.forEach(k=>{const t=M.trouble[k];if(!t)return;
    h+='<div class="tcard tr" onclick="go({s:\'trouble\',f:'+view.f+',m:\''+view.m+'\',gi:'+gi$()+',t:\''+k+'\'})">'
      +'<span class="ic">'+t.ic+'</span><div class="tt">'+esc(t.t)+'</div><div class="td">ไล่เช็กเป็นลำดับ '+t.steps.length+' ข้อ</div></div>';});
  h+='<div class="tcard" onclick="go({s:\'check\',f:'+view.f+',m:\''+view.m+'\',gi:'+gi$()+'})"><span class="ic">✅</span><div class="tt">เช็กลิสต์ก่อนลงไก่</div><div class="td">พิมพ์แปะหน้าเล้าได้</div></div>';
  h+='</div>';
  app.innerHTML=h;
}

function renderPage(M,g,tk,isTrouble){
  const t=(isTrouble?M.trouble:M.topics)[tk];
  if(!t)return go({s:'topics',f:view.f,m:view.m,gi:view.gi});
  const ov=(g&&g.over&&g.over[tk])||null;
  const no=isTrouble?null:TOPIC_ORDER.indexOf(tk)+1;
  let h='<div class="card"><div class="fname">'+t.ic+' '+(no?no+'. ':'')+esc(t.t)
    +' <span class="model">'+esc(M.name)+(g?' · '+esc(g.grp):'')+'</span></div>';
  if(t.why)h+='<div class="fsub">'+t.why+'</div>';
  if(!isTrouble)h+='<div class="howto">🎛 '+M.how+'</div>';
  t.steps.forEach((s,i)=>{h+='<div class="step"><div class="n">'+(i+1)+'</div><div class="b">'+s.k+(s.s?'<small>'+s.s+'</small>':'')+'</div></div>';});
  /* ค่าจริงของเล้านี้ (ถ้ามีใบตั้งค่า) มาก่อนตารางกลางเสมอ */
  if(ov){
    if(ov.rows)h+=tblHTML(T('📊 ค่าเฉพาะของ '+(g?g.grp:'')+' (คีย์ตามนี้)',['รายการ','ค่า'],ov.rows));
    if(ov.table)h+=tblHTML(ov.table);
    if(ov.note)h+='<div class="warn ok">📊 <b>ค่าจริงของ'+(g?' '+esc(g.grp):'ฟาร์มนี้')+':</b> '+ov.note+'</div>';
    if(ov.warnExtra)h+=warnHTML(ov.warnExtra);
  }
  /* หัวข้อที่ขึ้นกับจำนวนพัดลมของเล้า — เตือนทุกกรณี ไม่ว่าหน้านั้นจะมีตารางตัวอย่างหรือไม่ */
  if(g&&g.specPending&&PER_HOUSE.indexOf(tk)>=0)h+='<div class="warn w">⚠️ กลุ่ม '+esc(g.grp)+' <b>ยังไม่มีตัวเลขที่ยืนยัน</b> (ทราบแต่ว่าเป็นตู้ '+esc(M.name)+') — ตัวเลขข้างล่างเป็นตัวอย่างจากคู่มือ 🔴 ห้ามคีย์ตามตรง ๆ</div>';
  if(!g&&PER_HOUSE.indexOf(tk)>=0)h+='<div class="warn w">⚠️ หัวข้อนี้<b>ขึ้นกับจำนวนพัดลมและผังจับกลุ่มของเล้าแต่ละหลัง</b> — ขั้นตอนการกดใช้ได้เลย แต่ตัวเลข (Diff / ขั้นลม / เพดานพัดลม) 🔴 ห้ามคีย์ตามตัวอย่างตรง ๆ ต้องให้หมอออกใบตั้งค่าของเล้าคุณก่อน</div>';
  if(t.table){
    if(!g&&PER_HOUSE.indexOf(tk)>=0)h+='<div class="tcap" style="color:var(--amber)">↓ ตารางข้างล่างเป็น<b>ตัวอย่างจากคู่มือ</b> ไว้ดูวิธีไล่ค่าเท่านั้น</div>';
    else if(!g)h+='<div class="warn w">⚠️ ตัวเลขข้างล่างเป็นโปรไฟล์ที่กลุ่ม PPF ใช้ — ยืนยันกับหมอก่อนคีย์ลงเครื่องของฟาร์มคุณ</div>';
    h+=tblHTML(t.table);
  }
  h+=warnHTML(t.warn);
  if(t.ref)h+='<div class="ref">ที่มา: '+esc(t.ref)+'</div>';
  h+='<div class="pgact"><button class="pri" onclick="window.print()">🖨 พิมพ์หน้านี้ (แปะหน้าเล้า)</button>'
    +'<button onclick="reportPage('+(isTrouble?1:0)+',\''+tk+'\')">✏️ แจ้งแก้หน้านี้</button></div></div>';
  app.innerHTML=h;
}

function renderCheck(M,g){
  const list=(g&&g.checklist)?g.checklist:M.checklist;
  let h='<div class="card"><div class="fname">✅ เช็กลิสต์ก่อนลงไก่ <span class="model">'+esc(M.name)+(g?' · '+esc(g.grp):'')+'</span></div>';
  if(!g)h+='<div class="warn w">รายการนี้เป็นของรุ่น '+esc(M.name)+' ทั่วไป — เมื่อหมอออกใบตั้งค่าของเล้าคุณ จะมีรายการเฉพาะเล้า (เช่นจำนวนพัดลมที่ต้องเดินนับ) เพิ่มให้</div>';
  list.forEach(c=>{h+='<div class="step"><div class="n">☐</div><div class="b">'+c+'</div></div>';});
  h+='<div class="pgact"><button class="pri" onclick="window.print()">🖨 พิมพ์แปะหน้าเล้า</button>'
    +'<button onclick="reportPage(2,\'\')">✏️ แจ้งแก้หน้านี้</button></div></div>';
  app.innerHTML=h;
}

function reportPage(kind,tk){
  const f=farmOf(),g=groupOf(),M=MODELS[view.m];
  let title='เช็กลิสต์ก่อนลงไก่';
  if(kind!==2&&M){const t=(kind===1?M.trouble:M.topics)[tk];if(t)title=t.t;}
  const where=(f?f.name:'')+(g?' · '+g.grp:'')+' · '+(M?M.name:'')+' · หน้า "'+title+'"';
  alert('✏️ แจ้งแก้หน้านี้\n\n'+where+'\n\nวิธีแจ้งตอนนี้: แคปหน้าจอนี้ส่งให้ผู้ดูแลระบบ พร้อมบอกว่าเมนูหรือตัวเลขไหนไม่ตรงของจริง\nแก้ได้ทีละหน้า — หน้าอื่นไม่ถูกแตะ และทุกเครื่องได้หน้าใหม่พร้อมกัน\n\n(เฟสถัดไป: ปุ่มนี้จะเปิดฟอร์มแก้ในแอปได้เลย ใช้รหัสแก้ไขเดียวกับระบบซิงค์ พร้อมเก็บประวัติว่าใครแก้อะไร)');
}
/* ข้อมูลฟาร์มในแอปเปลี่ยน (ซิงค์/แก้ไข) → รีเฟรชรายชื่อ */
window.addEventListener('storage',e=>{if(e.key==='ppf_farms_v3'&&view.s==='home')render();});
/* เปิดหน้าแรกโดยโฟกัสฟาร์มที่กำลังดูอยู่ในแอป · ถ้าฟาร์มนั้นมีใบตั้งค่ากลุ่มเดียว → เข้าเลย */
(function init(){
  loadFarms();
  render();
  const i=curCf();
  if(FARMS[i]){
    const fs=setOf(FARMS[i].name);
    if(fs&&fs.groups.length===1){go({s:'topics',f:i,m:fs.groups[0].model,gi:0});return;}
    const el=document.querySelectorAll('#app .card')[i];
    if(el)setTimeout(()=>{try{el.scrollIntoView({block:'center'});}catch(_){}},60);
  }
})();
